\begin{exercise}[$\star\star\star$]\label{pb:sylvester}
\begin{enumerate}[label=(\alph*)]
\item (Fibonacci, 1202.) Let $0<\frac ab<1$ be rational. Subtract the largest unit fraction $\frac1n\le\frac ab$, and repeat
with the remainder. Show that the process stops, and writes $\frac ab$ as a sum of distinct unit fractions. Apply it to
$\frac4{13}$.
\item (Sylvester, 1880.) Let $s_0=2$ and $s_{k+1}=s_k^2-s_k+1$, so $2$, $3$, $7$, $43$, $1807$, \dots Show that
$\sum_{k=0}^N\frac1{s_k}=1-\frac1{s_{N+1}-1}$, and that the $s_k$ are pairwise coprime.
\item Show that there is a constant $E>1$ such that $s_k=\bigl\lfloor E^{2^{k+1}}+\frac12\bigr\rfloor$ for every $k\ge0$.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star$]\label{pb:mersennediv}
Let $p$ be an odd prime and $M_p=2^p-1$.
\begin{enumerate}[label=(\alph*)]
\item Show that every prime factor $q$ of $M_p$ satisfies $q\equiv1\pmod{2p}$ and $q\equiv\pm1\pmod8$.
\item Show that if $p\equiv3\pmod4$ and $2p+1$ is prime, then $2p+1$ divides $M_p$. Deduce that $M_{11}$, $M_{23}$ and
$M_{83}$ are composite.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star$]\label{pb:dice}
A die is a cube whose faces carry the numbers $1$ to $6$, each once. Two dice are the same if a rotation carries one onto the
other.
\begin{enumerate}[label=(\alph*)]
\item How many different dice are there?
\item On a standard die, opposite faces add up to $7$. How many different standard dice are there?
\item Show that no die is the same as its mirror image, so that the dice of (a) come in mirror pairs.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{pb:ksubsets}
Let $n\ge0$ be an integer and let $\pi_k(\sigma)$ count the $k$-element subsets of $\{1,\dots,n\}$ fixed by $\sigma\in\mathfrak S_n$. Let $k,l$ be integers with $0\le k,l\le\frac n2$.
\begin{enumerate}[label=(\alph*)]
\item Show that $\langle\pi_k,\pi_l\rangle=\min(k,l)+1$.
\item Deduce that $\chi_0=1$ and $\chi_k=\pi_k-\pi_{k-1}$ ($1\le k\le\frac n2$) are distinct irreducible characters of
$\mathfrak S_n$, of degrees $\binom nk-\binom n{k-1}$.
\item (Livingstone and Wagner.) Let $G\le\mathfrak S_n$. Show that the number of orbits of $G$ on $k$-subsets is a
non-decreasing function of $k$ for $0\le k\le\frac n2$.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star\star$]\label{pb:egz}
\emph{Erdős--Ginzburg--Ziv (1961).} For every integer $n\ge1$, we show that among any $2n-1$ integers there are $n$ whose sum is divisible by $n$.
\begin{enumerate}[label=(\alph*)]
\item Prove Chevalley--Warning for systems: let $m\ge1$, and let $f_1,\dots,f_r\in\mathbb F_p[x_1,\dots,x_m]$ have degree bounds $d_j\ge0$ with $\sum_jd_j<m$ (the zero polynomial is allowed with bound $0$). Then the number
of common zeros of the $f_j$ in $\mathbb F_p^m$ is divisible by $p$.
\item Prove the theorem for $n=p$ prime, with $f_1=\sum_ia_ix_i^{p-1}$ and $f_2=\sum_ix_i^{p-1}$.
\item Show that if the theorem holds for $m$ and for $n$, it holds for $mn$. Conclude.
\item Show that $2n-1$ cannot be replaced by $2n-2$.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{pb:abelian}
\emph{How many abelian groups? (Erdős and Szekeres, 1934).} For a positive integer $n$, let $A(n)$ be the number of abelian groups of order $n$, up to isomorphism.
\begin{enumerate}[label=(\alph*)]
\item Show that $A(n)=\prod_ip(e_i)$ if $n=\prod_ip_i^{e_i}$, and that $\sum_{n\ge1}A(n)n^{-s}=\prod_{k\ge1}\zeta(ks)$ for $s>1$.
\item For real $x\ge1$, show that $\sum_{n\le x}A(n)=cx+O(\sqrt x)$ with $c=\prod_{k\ge2}\zeta(k)=2.2948\ldots$: on average, there are about $2.29$
abelian groups of each order.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:perron2}
Let $A=\bigl(\begin{smallmatrix}a&b\\c&d\end{smallmatrix}\bigr)>0$. Compute $\rho$ and the Perron vector, and check directly
that the other eigenvalue has smaller modulus.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:rowsum}
For $A\ge0$ irreducible, show that $\min_i\sum_ja_{ij}\le\rho\le\max_i\sum_ja_{ij}$, with equality on either side only if all row
sums are equal.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:minmaxcw}
For $A>0$, show the dual Collatz--Wielandt formula $\rho=\min_{x>0}\max_i\frac{(Ax)_i}{x_i}$, and deduce that any $x>0$ gives
$\min_i\frac{(Ax)_i}{x_i}\le\rho\le\max_i\frac{(Ax)_i}{x_i}$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:monotone}
Let $0\le A\le B$ entrywise, with $B$ irreducible. Show that $\rho(A)\le\rho(B)$, with equality only if $A=B$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:nonneg}
Let $A\ge0$ be arbitrary. Show that $\rho(A)$ is an eigenvalue of $A$ with an eigenvector $x\ge0$, $x\ne0$. (Apply
Exercise~\ref{linear:ex:monotone} to $A+\varepsilon J$, where $J$ is the all-ones matrix, and let $\varepsilon\to0$.)
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:diagpos}
Show that an irreducible $A\ge0$ with a positive diagonal entry is primitive, and that if all diagonal entries are positive then
$A^{n-1}>0$.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:twostate}
For the two-state chain $P=\bigl(\begin{smallmatrix}1-a&a\\b&1-b\end{smallmatrix}\bigr)$ with $0<a,b<1$, find $\pi$ and an
explicit formula for $P^k$. What is the rate of convergence?
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{linear:ex:wielandtsharp}
Let $n\ge2$ and let $W$ be the Wielandt matrix (edges $i\to i+1$ for $i<n$, $n\to1$ and $n\to2$). Show that every positive-length closed walk at vertex $1$
has length $an+b(n-1)$ with $a\ge1$ and $b\ge0$, and deduce that $(W^{(n-1)^2})_{11}=0$, so that Theorem~\ref{linear:thm:wielandt} is
sharp.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:circalg}
Show that the $n\times n$ circulants form a commutative algebra of dimension $n$, closed under inverses and adjoints, and
compute $(I-tS)^{-1}$ explicitly for $t^n\ne1$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:circ3}
Show that an integer $N$ can be written $N=a^3+b^3+c^3-3abc$ with $a,b,c\in\Z$ if and only if $N\not\equiv\pm3\pmod9$.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:fourier}
Show that the Fourier matrix $F$ satisfies $F^2=R$, where $R$ is the reversal $x_j\mapsto x_{-j}$, and $F^4=I$. Deduce that the
eigenvalues of $F$ are among $1,-1,i,-i$.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:dualgroup}
Show that $\widehat{G\times H}\cong\widehat G\times\widehat H$, with $(\chi,\psi)\mapsto\bigl((x,y)\mapsto\chi(x)\psi(y)\bigr)$, and that
$\widehat{\Z/n}\cong\Z/n$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:convolution}
Define $(f*h)(x)=\sum_yf(y)h(x-y)$. Prove the convolution theorem $\widehat{f*h}=\hat f\,\hat h$ and Plancherel's formula
$\sum_x|f(x)|^2=\frac1{|G|}\sum_\chi|\hat f(\chi)|^2$. Show that the translation-invariant matrix with symbol $m$ acts on $f$ by
$f\mapsto m*f$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:walsh}
Show that $H_n=H_1\otimes H_{n-1}$ (in the block sense $\bigl(\begin{smallmatrix}H_{n-1}&H_{n-1}\\H_{n-1}&-H_{n-1}\end{smallmatrix}\bigr)$
for a suitable order of the words), and deduce an algorithm computing $H_nf$ with $n2^n$ additions and subtractions.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:krawgen}
Show that $\sum_{k=0}^nK_k(t)z^k=(1-z)^t(1+z)^{n-t}$ for integers $0\le t\le n$. Deduce that $K_k(n-t)=(-1)^kK_k(t)$ and that
$\sum_kK_k(t)=2^n[t=0]$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:gausssign}
Show that $g(a)=\bigl(\frac ap\bigr)g(1)$ for $a\ne0$, where $\bigl(\frac ap\bigr)$ is the Legendre symbol. Deduce that in $P_p$ the
eigenvalue $\frac{-1+\sqrt p}2$ belongs to the characters $\chi_a$ with $a$ a square if $g(1)>0$.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:paleyself}
Let $p\equiv1\pmod4$ and $c$ a non-square modulo $p$. Show that $x\mapsto cx$ is an isomorphism from $P_p$ to its complement.
Deduce again that $P_p$ and its complement have the same spectrum.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:paleyramsey}
Show that the clique number of $P_{17}$ is $3$, by hand or with the help of the bound $\sqrt{17}$. Deduce that the Ramsey number
$R(4,4)$ is at least $18$. Here $R(4,4)$ is the least vertex count forcing
a monochromatic four-clique in every red/blue colouring of the complete graph.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:plotkinsharp}
Show that a code achieving the Plotkin bound $|C|=\frac{2d}{2d-n}$ (with $2d>n$) has all its non-zero distances equal to $d$, and
that each coordinate takes the value $1$ in exactly half of its codewords.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{linear:ex:lpthree}
Plotkin's bound says nothing for $n=8$, $d=4$. Use Delsarte's inequalities for $k=1$ and $k=2$ to show that $A(8,4)\le16$, and find
a code of that size.
\end{exercise}

\begin{exercise}[$\star$]\label{combinatorial:ex:eventown}
Check that the couples construction satisfies the Eventown rules. Then let the inhabitants be the $8$ points of $\mathbb F_2^3$ and the clubs the $14$ affine planes (translates of $2$-dimensional subspaces),
together with $\varnothing$ and $\mathbb F_2^3$. Show that this is an Eventown family of maximum size which does not come from couples.
\end{exercise}

